#!/usr/bin/env node
/**
 * Writes @duncit/utils' copy of the HR enums and limits from the server's
 * `server/src/modules/hr/hr.constants.ts`.
 *
 * Why a generated file rather than an import: the server is the authority (it
 * re-checks every HR write) and imports no `@duncit/*` package by design (rule
 * 40), while the HR and Employee consoles need the same values to validate
 * their forms. Two hand-written copies are exactly the clone the duplication
 * gate refuses — and two copies can drift, so a form could accept what the
 * server refuses. Same arrangement as `generate-growth-formula.mjs`.
 *
 * Run `node scripts/generate-hr-constants.mjs` after editing the constants;
 * `--check` fails instead of writing, which is what CI runs so a stale copy
 * cannot ship.
 */
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const SOURCE = join(ROOT, "server/src/modules/hr/hr.constants.ts");
const OUT = join(ROOT, "packages/utils/src/generated/hr-constants.ts");
const NAME = "generate-hr-constants";
const check = process.argv.includes("--check");

const source = readFileSync(SOURCE, "utf8").replaceAll("\r\n", "\n");
// The copy must stand alone in every bundle: one import would pull a server
// module (or a path no client image copies) into it.
if (/^\s*import\s/m.test(source)) {
  console.error(`${NAME}: ${SOURCE} has an import — the constants file must import nothing`);
  process.exit(1);
}
const headerEnd = source.indexOf("*/\n");
if (!source.startsWith("/**") || headerEnd === -1) {
  console.error(`${NAME}: ${SOURCE} no longer opens with a doc comment — update this script`);
  process.exit(1);
}
const body = source.slice(headerEnd + 3).replace(/^\n+/, "");

const file = `/**
 * GENERATED by \`node scripts/generate-hr-constants.mjs\` from
 * \`server/src/modules/hr/hr.constants.ts\` — do not edit; change the server
 * file and regenerate.
 *
 * The HR and Employee consoles validate with this copy; the server re-checks
 * every write with the original. CI fails if the two differ.
 */

${body}`;

if (check) {
  let current = "";
  try {
    current = readFileSync(OUT, "utf8").replaceAll("\r\n", "\n");
  } catch {
    console.error(`${NAME}: ${OUT} is missing — run the script without --check`);
    process.exit(1);
  }
  if (current !== file) {
    console.error(
      `${NAME}: hr-constants.ts is out of date with the server constants.\n` +
        "Run `node scripts/generate-hr-constants.mjs` and commit the result.",
    );
    process.exit(1);
  }
  console.log(`${NAME}: hr-constants.ts matches the server constants`);
} else {
  mkdirSync(dirname(OUT), { recursive: true });
  writeFileSync(OUT, file, "utf8");
  console.log(`${NAME}: wrote ${OUT.slice(ROOT.length + 1)}`);
}
